from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, Image, Table, TableStyle
from reportlab.lib.units import cm
from reportlab.lib import colors

def build_pro_pdf(book_dir, title, subtitle):
    book_path = os.path.join(book_dir, "FIRST_GENERATION_COMPLETE.md" if "First" in title else "SECOND_GENERATION_COMPLETE.md")
    front_matter_path = os.path.join(book_dir, "FRONT_MATTER.md")
    back_matter_path = "/home/bob/books/BACK_COVER.md"
    cover_image = os.path.join(book_dir, f"{title.replace(' ', '_')}_Cover.png")
    output_pdf = os.path.join(book_dir, f"{title.replace(' ', '_')}_Final_Print.pdf")

    doc = SimpleDocTemplate(
        output_pdf,
        pagesize=A4,
        rightMargin=2.5*cm, leftMargin=2.5*cm, topMargin=2.5*cm, bottomMargin=2.5*cm
    )

    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(name='TOCItem', parent=styles['Normal'], fontName='Times-Roman', fontSize=12, leading=16))
    styles.add(ParagraphStyle(name='MainText', parent=styles['Normal'], fontName='Times-Roman', fontSize=12, leading=16, alignment=4))
    styles.add(ParagraphStyle(name='DialogueSnippet', parent=styles['Italic'], fontName='Times-Italic', fontSize=11, leftIndent=1.5*cm, rightIndent=1.5*cm, spaceAfter=6))
    styles.add(ParagraphStyle(name='ChapterTitle', parent=styles['Heading1'], fontName='Times-Bold', fontSize=18, spaceAfter=20, alignment=1))

    story = []

    # 1. Full Page Cover
    if os.path.exists(cover_image):
        img = Image(cover_image, width=16*cm, height=24*cm)
        story.append(img)
        story.append(PageBreak())

    # 2. Front Matter
    if os.path.exists(front_matter_path):
        with open(front_matter_path, 'r') as f:
            for line in f:
                line = line.strip()
                if line.startswith('---'): story.append(PageBreak())
                elif line.startswith('# '): story.append(Paragraph(line[2:], styles['Heading1']))
                elif line.startswith('## '): story.append(Paragraph(line[3:], styles['Italic']))
                elif line.startswith('### '): story.append(Paragraph(line[4:], styles['Heading3']))
                else: story.append(Paragraph(line, styles['Normal']))

    # 3. Dynamic TOC (Placeholder for visual structure)
    story.append(PageBreak())
    story.append(Paragraph("Table of Contents", styles['Heading1']))
    story.append(Spacer(1, 20))

    chapters = []
    with open(book_path, 'r') as f:
        for line in f:
            if line.startswith('## Chapter'):
                chapters.append(line.strip()[3:])

    for ch in chapters:
        story.append(Paragraph(ch, styles['TOCItem']))

    story.append(PageBreak())

    # 4. Content
    with open(book_path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line: continue
            if line.startswith('## Chapter'):
                story.append(PageBreak())
                story.append(Paragraph(line[3:], styles['ChapterTitle']))
            elif line.startswith('*'):
                story.append(Paragraph(line.replace('*',''), styles['DialogueSnippet']))
            elif line.startswith('---'):
                story.append(Spacer(1, 24))
            else:
                story.append(Paragraph(line, styles['MainText']))

    # 5. Back Matter
    if os.path.exists(back_matter_path):
        story.append(PageBreak())
        with open(back_matter_path, 'r') as f:
            for line in f:
                line = line.strip()
                if line.startswith('---'): story.append(Spacer(1, 24))
                elif line.startswith('# '): story.append(Paragraph(line[2:], styles['Heading1']))
                else: story.append(Paragraph(line, styles['Normal']))

    doc.build(story)
    return output_pdf

# Run for both
